		Statement tail = VF.createStatement(VF.createIRI("urn:bulk-flush:final-tail"), PREDICATE, OBJECT);
		Iterable<Statement> input = () -> IntStream.range(0, 200_001).mapToObj(index -> switch (index) {
		case 99_999 -> first;
		case 199_999 -> second;
		case 200_000 -> tail;
		default -> seed;
		}).iterator();
		Set<Statement> expected = Set.of(seed, first, second, tail);
		NativeStore store = new NativeStore(dataDir.toFile(), "spoc");
