	@Test
	void flushingBulkHookPreservesEveryRowAndContext() {
		AtomicInteger hooks = new AtomicInteger();
		NativeStore store = flushingStore(hooks);
		List<Statement> rows = new ArrayList<>();
		for (int i = 0; i < 7; i++) {
			rows.add(VF.createStatement(VF.createIRI("urn:bulk-flush:hook:" + i), PREDICATE, OBJECT,
					i % 2 == 0 ? null : VF.createIRI("urn:bulk-flush:graph")));
		}
		store.init();
		try {
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				connection.addStatements(rows);
				connection.commit();
				assertEquals(Set.copyOf(rows), statements(connection));
				assertEquals(rows.size(), hooks.get(), "one hook must run for each input row");
			}
		} finally {
			store.shutDown();
		}
		assertReopened(Set.copyOf(rows));
	}

	@Test
	void flushingBulkHookPreservesDuplicateContextOverrides() {
		AtomicInteger hooks = new AtomicInteger();
		NativeStore store = flushingStore(hooks);
		Statement first = VF.createStatement(VF.createIRI("urn:bulk-flush:first"), PREDICATE, OBJECT,
				VF.createIRI("urn:bulk-flush:ignored"));
		Statement second = VF.createStatement(VF.createIRI("urn:bulk-flush:second"), PREDICATE, OBJECT);
		IRI context = VF.createIRI("urn:bulk-flush:override");
		Set<Statement> expected = Set.of(VF.createStatement(first.getSubject(), PREDICATE, OBJECT),
				VF.createStatement(first.getSubject(), PREDICATE, OBJECT, context),
				VF.createStatement(second.getSubject(), PREDICATE, OBJECT),
				VF.createStatement(second.getSubject(), PREDICATE, OBJECT, context));
		store.init();
		try {
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				connection.addStatements(List.of(first, first, second), null, context, context);
				connection.commit();
				assertEquals(expected, statements(connection));
				assertEquals(3, hooks.get(), "context expansion must not multiply storage hook calls");
			}
		} finally {
			store.shutDown();
		}
		assertReopened(expected);
	}

	@Test
	void iteratorFailurePreservesExactlyItsApprovedPrefix() {
		NativeStore store = flushingStore(new AtomicInteger());
		Statement first = VF.createStatement(VF.createIRI("urn:bulk-flush:first"), PREDICATE, OBJECT);
		Statement second = VF.createStatement(VF.createIRI("urn:bulk-flush:second"), PREDICATE, OBJECT);
		IllegalStateException failure = new IllegalStateException("input stopped after its approved prefix");
		Iterable<Statement> input = () -> new Iterator<>() {
			private int index;

			@Override
			public boolean hasNext() {
				return true;
			}

			@Override
			public Statement next() {
				return switch (index++) {
				case 0 -> first;
				case 1 -> second;
				default -> throw failure;
				};
			}
		};
		store.init();
		try {
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				assertSame(failure, assertThrows(IllegalStateException.class, () -> connection.addStatements(input)));
				connection.commit();
				assertEquals(Set.of(first, second), statements(connection));
			}
		} finally {
			store.shutDown();
		}
		assertReopened(Set.of(first, second));
	}

	@Test
	void bulkWithListenersRetainsDuplicateNotifications() {
		NativeStore store = new NativeStore(dataDir.toFile(), "spoc");
		Statement row = VF.createStatement(VF.createIRI("urn:bulk-flush:listener"), PREDICATE, OBJECT);
		List<Statement> notifications = new ArrayList<>();
		store.init();
		try {
			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.addConnectionListener(new SailConnectionListener() {
					@Override
					public void statementAdded(Statement statement) {
						notifications.add(statement);
					}

					@Override
					public void statementRemoved(Statement statement) {
						throw new AssertionError("a bulk insertion cannot remove a statement");
					}
				});
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.addStatements(List.of(row, row));
				connection.commit();
				assertEquals(Set.of(row), statements(connection));
				assertEquals(List.of(row, row), notifications);
			}
		} finally {
			store.shutDown();
		}
	}

