	private void assertAutomaticFlush(int seedCalls, int tailSize, String shape, boolean scalar) {
		Statement seed = VF.createStatement(VF.createIRI("urn:bulk-flush:seed"), PREDICATE, OBJECT);
		List<Statement> tail = new ArrayList<>();
		for (int i = 0; i < tailSize; i++) {
			tail.add(VF.createStatement(VF.createIRI("urn:bulk-flush:tail:" + i), PREDICATE, OBJECT));
		}
		Set<Statement> expected = new LinkedHashSet<>(tail);
		expected.add(seed);
		NativeStore store = new NativeStore(dataDir.toFile(), "spoc");
		store.init();
		Set<Statement> committed;
		try {
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				for (int i = 0; i < seedCalls; i++) {
					connection.addStatement(seed.getSubject(), seed.getPredicate(), seed.getObject());
				}
				if (scalar) {
					for (Statement statement : tail) {
						connection.addStatement(statement.getSubject(), statement.getPredicate(),
								statement.getObject());
					}
				} else {
					connection.addStatements(input(tail, shape));
				}
				connection.commit();
				committed = statements(connection);
			}
		} finally {
			store.shutDown();
		}
		Set<Statement> reopened = reopenedStatements();
		assertAll(() -> assertEquals(expected, committed, "committed graph must contain the exact input set"),
				() -> assertEquals(expected, reopened, "reopened graph must contain the exact committed set"));
	}

	private Iterable<Statement> input(List<Statement> rows, String shape) {
		if (shape.equals("set")) {
			return new LinkedHashSet<>(rows);
		}
		if (shape.equals("lazy")) {
			return new Iterable<>() {
				private boolean opened;

				@Override
				public Iterator<Statement> iterator() {
					if (opened) {
						throw new AssertionError("bulk input must be consumed once");
					}
					opened = true;
					return rows.iterator();
				}
			};
		}
		return rows;
	}

	private void assertReopened(Set<Statement> expected) {
		assertEquals(expected, reopenedStatements(), "reopened graph must contain the exact committed set");
	}

	private Set<Statement> reopenedStatements() {
		NativeStore reopened = new NativeStore(dataDir.toFile(), "spoc");
		reopened.init();
		try {
			try (SailConnection connection = reopened.getConnection()) {
				return statements(connection);
			}
		} finally {
			reopened.shutDown();
		}
	}

	private Set<Statement> statements(SailConnection connection) {
		try (var result = connection.getStatements(null, null, null, false)) {
			return new LinkedHashSet<>(Iterations.asList(result));
		}
	}
